reference_solution:
def maximum_candy_tastiness(price,k):
    price=sorted(price)
    def possible(gap):
        chosen=1;last=price[0]
        for value in price[1:]:
            if value-last>=gap:chosen+=1;last=value
        return chosen>=k
    low=0;high=price[-1]-price[0]
    while low<high:
        middle=(low+high+1)//2
        if possible(middle):low=middle
        else:high=middle-1
    return low

